using System;
using System.Collections.Immutable;
using System.Linq;
using Extensions.Pack;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("AsyncAwait")]
    [TestClass]
    public class RJIT_CR_AA_C_00001 : MsTestBase
    {
        /*
         * Code Rule RJIT_CR_AA_00001 enforces a naming convention in C# async programming, ensuring all asynchronous methods returning a Task or Task<T> are properly named with an "Async" suffix. 
         */
        
        [TestMethod]
        public void All_Classes_Which_Return_A_Task_Should_Have_Post_Fix_Async()
        {
            var returnAwaitOnly = (from @class in Classes
                from @method in @class.Methods
                where method.ReturnParameter.Contains("Task") && method.Name.EndWith("Async").IsFalse()
                where method.Name.NotEqualsTo("Handle")
                where method.Name.NotEqualsTo("Main")
                select new
                {
                    ErrorClass = @class.FullQualifiedName,
                    ErrorMethod = method.Name,
                    Error = $@"
Please name your async methods correctly with postfix 'Async'.
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Class:  {@class.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Method: {method.Name}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample: {method.Name}Async
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                }).ToImmutableList();

            Assert.IsTrue(returnAwaitOnly.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_AA_00001

Please name your async methods correctly with postfix 'Async'. Findings {returnAwaitOnly.Count}': {Environment.NewLine}{returnAwaitOnly.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
